<?php require_once __DIR__.'/../includes/functions.php';require_role('teacher');$s=$pdo->prepare("SELECT c.name FROM teacher_classes tc JOIN teachers t ON t.id=tc.teacher_id JOIN classes c ON c.id=tc.class_id WHERE t.user_id=?");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='My Classes';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>My Classes</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>